const buffer = msg.payload;

// Re-attach the radio metadata stashed by the gateway adapter (see
// gw-decode-fn). Absent for anything that did not arrive via a gateway - a
// replayed packet or an injected test - so every consumer must treat it as
// optional.
if (Buffer.isBuffer(buffer)) {
    const gwStore = global.get('gwmeta') || {};
    const gwKey = buffer.toString('hex');
    if (gwStore[gwKey]) {
        msg.gateway = gwStore[gwKey].meta;
        delete gwStore[gwKey];
        global.set('gwmeta', gwStore);
    }
}

if (!buffer) {
    msg.payload = { error: 'Invalid parameters' };
    msg.topic = 'lora/out/error';
    return msg;
}

const protocolVersion = buffer.readUInt8(0);
const messageType = buffer.readUInt8(1);
let packet = {};

try {
    if (messageType === 0x01 && buffer.length === 48) {
        const nodeId = buffer.readUInt32LE(4);
        if (nodeId === 0) {
            msg.payload = { error: 'Invalid packet data - nodeId is 0' };
            msg.topic = 'lora/out/error';
            return msg;
        }

        const digitalBits = buffer.readUInt16LE(20);
        const digitalArray = [];
        for (let i = 0; i < 16; i++) {
            digitalArray.push((digitalBits >> i) & 1);
        }

        const busSlots = [
            buffer.readUInt16LE(30),
            buffer.readUInt16LE(32),
            buffer.readUInt16LE(34),
            buffer.readUInt16LE(36),
            buffer.readUInt16LE(38),
            buffer.readUInt16LE(40),
            buffer.readUInt16LE(42),
            buffer.readUInt16LE(44)
        ];

        const gpioAnalog = [
            buffer.readUInt16LE(22),
            buffer.readUInt16LE(24),
            buffer.readUInt16LE(26),
            buffer.readUInt16LE(28)
        ];

        packet = {
            protocol: protocolVersion,
            type: 'sensor',
            nodeId: nodeId,
            nodeFlags: buffer.readUInt8(2),
            counter: buffer.readUInt32LE(8),
            uptime: buffer.readUInt32LE(12),
            battery: buffer.readUInt8(16),
            voltage: buffer.readUInt16LE(17),
            gpio: {
                digitalBitmask: digitalBits,
                digital: digitalArray,
                analog: gpioAnalog
            },
            bus: {
                discoveredSensors: buffer.readUInt8(46),
                slots: busSlots
            },
            // Flat convenience aliases for threshold processing
            analog: busSlots,
            digital: digitalBits,
            discoveredSensors: buffer.readUInt8(46)
        };
        msg.topic = 'lora/out/sensor';
    } else if (messageType === 0x02 && buffer.length >= 35) {
        const nodeId = buffer.readUInt32LE(4);
        packet = {
            protocol: protocolVersion,
            type: 'gnss',
            nodeId: nodeId,
            counter: buffer.readUInt32LE(8),
            uptime: buffer.readUInt32LE(12),
            battery: buffer.readUInt8(16),
            voltage: buffer.readUInt16LE(17),
            latitude: buffer.readFloatLE(20),
            longitude: buffer.readFloatLE(24),
            speed: buffer.readFloatLE(28),
            hdop: buffer.readUInt8(32) / 10.0,
            course: buffer.readFloatLE(33)
        };
        msg.topic = 'lora/out/gnss';
    } else {
        msg.payload = { error: 'Unknown packet: type=0x' + messageType.toString(16) + ' len=' + buffer.length };
        msg.topic = 'lora/out/error';
        return msg;
    }
} catch (e) {
    msg.payload = { error: 'Parsing error: ' + e.message };
    msg.topic = 'lora/out/error';
    return msg;
}

// Signal quality belongs with the reading, not just in the flow: it is the
// first thing you want when a node goes quiet, and lora/out is what everything
// downstream consumes.
if (msg.gateway) packet.radio = msg.gateway;

msg.payload = packet;
return msg;

const rows = msg.payload;
const sensorData = msg.sensorData;

if (!rows || rows.length === 0) {
    node.warn("Unknown device for nodeId: " + msg.nodeId);
    node.send([null, null, {nodeId: msg.nodeId, sensorData: sensorData}]);
    return null;
}

const device = rows[0];
const alerts = [];

// 1. Digital Pin Transitions (D0..D15)
if (device.digital_pins && sensorData.gpio && sensorData.gpio.digitalBitmask !== undefined) {
    device.digital_pins.forEach(pin => {
        const pinState = (sensorData.gpio.digitalBitmask >> pin.pin_index) & 1;
        const dStateKey = "state_digital_" + device.device_id + "_" + pin.pin_index;

        // "Change" reports every transition and has no alarm/normal side. The
        // schema has always permitted this value but nothing implemented it, so
        // a pin configured this way went silent rather than failing loudly.
        if (pin.trigger === "Change") {
            const nowRaw = pinState ? "ON" : "OFF";
            const prevRaw = flow.get(dStateKey);
            flow.set(dStateKey, nowRaw);
            // Seed the baseline on first sight, so a restart cannot invent a change.
            if (prevRaw !== undefined && prevRaw !== nowRaw) {
                alerts.push({
                    deviceId: device.device_id,
                    ownerName: device.owner_name || "nolfonzo",
                    ownerEmail: device.owner_email || "nolfonzo@gmail.com",
                    notifyVia: device.notify_via || "email",
                    deviceName: device.display_name,
                    nodeId: msg.nodeId,
                    pinLabel: pin.label || ("Digital " + pin.pin_index),
                    state: nowRaw,
                    alertMessage: (pin.label || "Input") + " changed to " + nowRaw,
                    alertLevel: pin.alert_level || "Medium",
                    action: "TRIGGERED"
                });
            }
            return;
        }

        let isTriggered = false;
        if (pin.trigger === "High" && pinState === 1) isTriggered = true;
        else if (pin.trigger === "Low" && pinState === 0) isTriggered = true;

        const prevDState = flow.get(dStateKey) || "NORMAL";
        const newDState = isTriggered ? "TRIGGERED" : "NORMAL";

        if (newDState !== prevDState) {
            flow.set(dStateKey, newDState);
            alerts.push({
                deviceId: device.device_id,
                ownerName: device.owner_name || "nolfonzo",
                ownerEmail: device.owner_email || "nolfonzo@gmail.com",
                notifyVia: device.notify_via || "email",
                deviceName: device.display_name,
                nodeId: msg.nodeId,
                pinLabel: pin.label || ("Digital " + pin.pin_index),
                state: newDState,
                alertMessage: newDState === "TRIGGERED" ? 
                    ("ALERT: " + (pin.label || "Input") + " triggered (" + pin.trigger + ")") :
                    ("RESOLVED: " + (pin.label || "Input") + " returned to normal"),
                alertLevel: newDState === "TRIGGERED" ? (pin.alert_level || "High") : "Info",
                action: newDState === "TRIGGERED" ? "TRIGGERED" : "RESOLVED"
            });
        }
    });
}

// 2. Physical GPIO Analog Pin Transitions (A0..A3)
if (device.analog_pins && sensorData.gpio && sensorData.gpio.analog) {
    device.analog_pins.forEach(pin => {
        const value = sensorData.gpio.analog[pin.pin_index];
        if (value === undefined) return;

        let newState = "NORMAL";
        if (pin.low_threshold !== null && value < pin.low_threshold) newState = "LOW";
        else if (pin.high_threshold !== null && value > pin.high_threshold) newState = "HIGH";

        const stateKey = "state_analog_" + device.device_id + "_" + pin.pin_index;
        const prevState = flow.get(stateKey) || "NORMAL";

        if (newState !== prevState) {
            flow.set(stateKey, newState);
            const valStr = value + " (Raw/mV)";
            alerts.push({
                deviceId: device.device_id,
                ownerName: device.owner_name || "nolfonzo",
                ownerEmail: device.owner_email || "nolfonzo@gmail.com",
                notifyVia: device.notify_via || "email",
                deviceName: device.display_name,
                nodeId: msg.nodeId,
                pinLabel: pin.label || ("Physical Analog " + pin.pin_index),
                state: newState,
                alertMessage: newState === "LOW" ? ("LOW WARNING: " + valStr) :
                              newState === "HIGH" ? ("HIGH WARNING: " + valStr) :
                              ("RESOLVED: Restored to normal (" + valStr + ")"),
                alertLevel: newState === "NORMAL" ? "Info" : (pin.alert_level || "High"),
                action: newState === "NORMAL" ? "RESOLVED" : "TRIGGERED"
            });
        }
    });
}

// 3. Digital Bus / I2C Telemetry Slots Transitions (Bus Slots 0..7)
const busSlots = (sensorData.bus && sensorData.bus.slots) ? sensorData.bus.slots : sensorData.analog;
if (device.bus_pins && busSlots) {
    device.bus_pins.forEach(pin => {
        const value = busSlots[pin.pin_index];
        if (value === undefined) return;

        let newState = "NORMAL";
        if (pin.low_threshold !== null && value < pin.low_threshold) newState = "LOW";
        else if (pin.high_threshold !== null && value > pin.high_threshold) newState = "HIGH";

        const stateKey = "state_bus_" + device.device_id + "_" + pin.pin_index;
        const prevState = flow.get(stateKey) || "NORMAL";

        if (newState !== prevState) {
            flow.set(stateKey, newState);
            const vStr = (value / 1000).toFixed(2) + "V";
            const lowStr = pin.low_threshold !== null ? (pin.low_threshold / 1000).toFixed(2) + "V" : "";
            const highStr = pin.high_threshold !== null ? (pin.high_threshold / 1000).toFixed(2) + "V" : "";

            alerts.push({
                deviceId: device.device_id,
                ownerName: device.owner_name || "nolfonzo",
                ownerEmail: device.owner_email || "nolfonzo@gmail.com",
                notifyVia: device.notify_via || "email",
                deviceName: device.display_name,
                nodeId: msg.nodeId,
                pinLabel: pin.label || ("Bus Slot " + pin.pin_index),
                state: newState,
                alertMessage: newState === "LOW" ? ("LOW VOLTAGE WARNING: " + vStr + " (Threshold: < " + lowStr + ")") :
                              newState === "HIGH" ? ("HIGH VOLTAGE / OVERCHARGE WARNING: " + vStr + " (Threshold: > " + highStr + ")") :
                              ("RESOLVED: Voltage restored to normal operating range (" + vStr + ")"),
                alertLevel: newState === "NORMAL" ? "Info" : (pin.alert_level || "High"),
                action: newState === "NORMAL" ? "RESOLVED" : "TRIGGERED"
            });
        }
    });
}

// 4. Heltec Internal 18650 Battery State Transitions
if (sensorData.battery !== undefined && sensorData.battery > 0) {
    let nodeBatState = (sensorData.battery <= 20) ? "LOW" : "NORMAL";
    const nodeBatKey = "state_node_bat_" + device.device_id;
    const prevNodeBatState = flow.get(nodeBatKey) || "NORMAL";

    if (nodeBatState !== prevNodeBatState) {
        flow.set(nodeBatKey, nodeBatState);
        const batPctStr = sensorData.battery + "%";
        const batVStr = sensorData.voltage ? (" (" + (sensorData.voltage / 1000).toFixed(2) + "V)") : "";

        alerts.push({
            deviceId: device.device_id,
            ownerName: device.owner_name || "nolfonzo",
            ownerEmail: device.owner_email || "nolfonzo@gmail.com",
            notifyVia: device.notify_via || "email",
            deviceName: device.display_name,
            nodeId: msg.nodeId,
            pinLabel: "Transmitter 18650 Battery",
            state: nodeBatState,
            alertMessage: nodeBatState === "LOW" ? 
                ("TRANSMITTER 18650 BATTERY LOW: " + batPctStr + batVStr + " (Threshold: <= 20%)") :
                ("RESOLVED: Transmitter 18650 battery recharged (" + batPctStr + ")"),
            alertLevel: nodeBatState === "LOW" ? "Medium" : "Info",
            action: nodeBatState === "LOW" ? "TRIGGERED" : "RESOLVED"
        });
    }
}

// Log event to PostgreSQL
const logMsg = {
    query: "INSERT INTO events (device_id, node_id, message_type, payload) VALUES ($1, $2, $3, $4::jsonb)",
    params: [device.device_id, msg.nodeId, sensorData.type, JSON.stringify(sensorData)],
    payload: ""
};
node.send([null, logMsg, null]);

// Dispatch transition alerts
if (alerts.length > 0) {
    alerts.forEach(alert => {
        // The router needs somewhere to send a Telegram alert. Attached here
        // rather than at each push site, of which there are five.
        alert.telegramChatId = device.telegram_chat_id || null;
        alert.pairCode = device.pair_code || null;
        alert.ownerMuted = device.owner_muted === true;
        const alertMsg = {
            query: "INSERT INTO alerts (device_id, pin_label, alert_message, alert_level) VALUES ($1, $2, $3, $4) ON CONFLICT (device_id, pin_label) DO UPDATE SET alert_message = EXCLUDED.alert_message, count = alerts.count + 1, updated_at = NOW()",
            params: [alert.deviceId, alert.pinLabel, alert.alertMessage, alert.alertLevel],
            payload: "",
            alert: alert
        };
        node.send([alertMsg, null, null]);
    });
}

return null;

// Route an alert to whichever channels its owner asked for.
//
// notify_via has been in the schema since the beginning but nothing ever read
// it - this node emailed unconditionally. Email was the channel we happened to
// build first, not a decision, and some people would rather not get mail at all.
//
// Output 1: email status (as before). Output 2: a Telegram send.

const alert = msg.alert;
if (!alert) {
    node.warn('send-notification: no alert data');
    return null;
}

// Muted covers every channel, checked before anything else so there is one
// place this is decided rather than one per channel.
if (alert.ownerMuted) {
    node.status({ fill: 'grey', shape: 'ring', text: 'muted: ' + alert.deviceName });
    return null;
}

const via = String(alert.notifyVia || 'email').toLowerCase();

let wantEmail = (via === 'email' || via === 'both');
let wantTelegram = (via === 'telegram' || via === 'both');

// An owner set to Telegram who has not paired yet would otherwise receive
// nothing at all, and silence is the one failure mode an alerting system must
// never have. Fall back to email and say so loudly.
if (wantTelegram && !alert.telegramChatId) {
    node.warn('Owner ' + alert.ownerName + ' is set to "' + via +
              '" but has no paired Telegram chat - falling back to email');
    wantTelegram = false;
    wantEmail = true;
}

if (via === 'none') {
    node.status({ fill: 'grey', shape: 'ring', text: 'muted: ' + alert.ownerName });
    return null;
}

const tag = alert.action === 'RESOLVED' ? '[RESOLVED]' : '[ALERT]';
const subject = tag + ' ' + alert.pinLabel + ' on ' + alert.deviceName;

let telegramMsg = null;
if (wantTelegram) {
    const icon = alert.action === 'RESOLVED' ? '✅' : '⚠️';
    telegramMsg = {
        tgChatId: alert.telegramChatId,
        tgText: icon + ' *' + (alert.action === 'RESOLVED' ? 'Resolved' : 'Alert') + '*\n' +
                alert.deviceName + ' — ' + alert.pinLabel + '\n' +
                alert.alertMessage + '\n' +
                '_' + alert.alertLevel + '_',
        tgButtons: [[
            { text: 'Status', callback_data: 'status' },
            { text: 'Watch 30m', callback_data: 'verbose:' + alert.nodeId + ':30' }
        ]]
    };
}

if (wantEmail) {
    const user = env.get('NOTIFY_EMAIL_USER');
    const pass = env.get('NOTIFY_EMAIL_PASS');
    const recipient = alert.ownerEmail || user;

    if (!pass) {
        node.error('NOTIFY_EMAIL_PASS not set in the environment - cannot send mail');
    } else {
        // Every alert doubles as an invitation until they take it up, then
        // the footer disappears on its own. This is the main reminder surface
        // - it reaches them wherever they already are, with nothing to look up.
        let footer = '';
        const botName = global.get('tgBotUsername');
        if (!alert.telegramChatId && alert.pairCode && botName) {
            footer = `
---
Prefer Telegram? It can answer "how is my boat right now", show live readings
while you are standing on the dock, and deliver alerts instantly. One tap:

    https://t.me/${botName}?start=${alert.pairCode}

Email keeps working either way.
`;
        }

        const body = `SensorSentinel Alert Notification

Owner: ${alert.ownerName || 'User'}
Device: ${alert.deviceName} (Node ID: ${alert.nodeId})
Sensor: ${alert.pinLabel}
Status: ${alert.alertMessage}
Alert Level: ${alert.alertLevel}
Timestamp: ${new Date().toISOString()}
${footer}`;
        try {
            const transporter = nodemailer.createTransport({
                host: env.get('NOTIFY_SMTP_HOST') || 'smtp.gmail.com',
                port: 465,
                secure: true,
                auth: { user: user, pass: pass }
            });

            transporter.sendMail({
                from: '"SensorSentinel" <' + user + '>',
                to: recipient,
                subject: subject,
                text: body
            }).then(info => {
                node.warn('SUCCESS: Sent ' + tag + ' email to ' + recipient + ' (msgId: ' + info.messageId + ')');
            }).catch(err => {
                node.error('ERROR: Failed sending to ' + recipient + ': ' + err.message);
            });
        } catch (e) {
            node.error('Nodemailer exception: ' + e.message);
        }
    }
}

node.status({ fill: 'blue', shape: 'dot',
              text: via + ' -> ' + alert.deviceName });

return [msg, telegramMsg];

const nodeId = msg.nodeId;
const displayName = 'Node-' + nodeId.toString(16).padStart(8, '0').toUpperCase();
msg.query = 'INSERT INTO devices (node_id, display_name) VALUES ($1, $2) ON CONFLICT (node_id) DO NOTHING';
msg.params = [nodeId, displayName];
msg.newDeviceName = displayName;
return msg;

msg.topic = 'sentinel/new_device';
msg.payload = JSON.stringify({
    nodeId: msg.nodeId,
    displayName: msg.newDeviceName,
    firstSeen: new Date().toISOString()
});
return msg;

let env = msg.payload;

if (Buffer.isBuffer(env)) env = env.toString('utf8');
if (typeof env === 'string') {
    try { env = JSON.parse(env); }
    catch (e) {
        node.warn('gateway: payload is not JSON: ' + String(env).slice(0, 80));
        return null;
    }
}
if (!env || typeof env !== 'object' || !env.data) {
    node.warn('gateway: no data field in envelope');
    return null;
}

let buf;
try { buf = Buffer.from(env.data, 'base64'); }
catch (e) { node.warn('gateway: base64 decode failed'); return null; }

if (!buf.length) { node.warn('gateway: empty payload'); return null; }

msg.gateway = {
    eui:  (msg.topic || '').split('/')[1] || null,
    freq: env.freq  !== undefined ? env.freq  : null,
    datr: env.datr  !== undefined ? env.datr  : null,
    rssi: env.rssi  !== undefined ? env.rssi  : null,
    snr:  env.lsnr  !== undefined ? env.lsnr  : null,
    size: env.size  !== undefined ? env.size  : buf.length
};

node.status({ fill: 'green', shape: 'dot',
              text: 'rx ' + buf.length + 'B rssi ' + msg.gateway.rssi });

// Carry the radio metadata across the MQTT hop. Only the raw binary is
// republished to lora/in, so rssi/snr/freq would otherwise be lost before the
// parser ever sees them - the packet arrives with no record of how well it was
// heard. Keyed on the payload bytes, which gives exact correlation without
// changing the wire format.
const gwKey = buf.toString('hex');
const gwStore = global.get('gwmeta') || {};
gwStore[gwKey] = { meta: msg.gateway, at: Date.now() };
// Prune anything the parser never collected. A malformed packet that fails to
// parse would otherwise leave its entry here for ever.
const gwCutoff = Date.now() - 120000;
for (const k of Object.keys(gwStore)) {
    if (gwStore[k].at < gwCutoff) delete gwStore[k];
}
global.set('gwmeta', gwStore);

msg.payload = buf;
msg.topic = 'lora/in/gw';
return msg;

// Semtech UDP packet forwarder -> the same MQTT envelope the HT-M7603 emits,
// so a Dragino/RAK/sx1302_hal gateway feeds the Gateway Adapter below without a
// second translation path, and no vendor's proprietary MQTT mode can trap us.
//
//   byte  0     protocol version (0x02)
//   bytes 1-2   token, echoed in the ACK
//   byte  3     packet type
//   bytes 4-11  gateway EUI (PUSH_DATA / PULL_DATA)
//   bytes 12+   JSON payload (PUSH_DATA only)

const PUSH_DATA = 0x00, PUSH_ACK = 0x01;
const PULL_DATA = 0x02, PULL_ACK = 0x04;

const buf = msg.payload;
if (!Buffer.isBuffer(buf) || buf.length < 4) { return null; }

const token = buf.slice(1, 3);
const kind = buf[3];

// A forwarder that gets no ACK decides the server is down and starts buffering,
// so acknowledge before anything that might fail.
if (kind === PULL_DATA) {
    // Downlink keepalive. We never transmit, but without the ACK the gateway
    // logs the server as unreachable.
    const pull = Buffer.concat([Buffer.from([0x02]), token, Buffer.from([PULL_ACK])]);
    return [{ payload: pull, ip: msg.ip, port: msg.port }, null];
}
if (kind !== PUSH_DATA) { return null; }

const ack = Buffer.concat([Buffer.from([0x02]), token, Buffer.from([PUSH_ACK])]);
const ackMsg = { payload: ack, ip: msg.ip, port: msg.port };

if (buf.length < 12) { return [ackMsg, null]; }
const eui = buf.slice(4, 12).toString('hex').toUpperCase();

const body = buf.slice(12);
if (body.length === 0) { return [ackMsg, null]; }   // keepalive with no payload

let parsed;
try {
    parsed = JSON.parse(body.toString('utf8'));
} catch (e) {
    node.warn('udp: undecodable JSON from ' + msg.ip + ' (' + body.length + ' bytes)');
    return [ackMsg, null];
}

// freq/datr/rssi/lsnr/size/data already match the Heltec envelope; the extra
// Semtech fields (tmst, chan, codr) are ignored downstream.
const out = [];
for (const rxpk of (parsed.rxpk || [])) {
    out.push({ topic: 'GWID/' + eui + '/UP', payload: rxpk });
}

if (out.length > 0) {
    node.status({ fill: 'green', shape: 'dot', text: eui + ' ' + out.length + ' pkt' });
}
return [ackMsg, out];

// One physical transmission can reach us by several independent paths: the
// HT-M7603 via GWID/<eui>/UP, a Heltec receiver via lora/in, and any second
// gateway added later. Each forwards without knowing the others exist, so the
// on-device caches (_seenPackets in the repeater, receivedCache in the
// receiver) cannot catch it - they only ever see their own copy.
//
// Time-windowed rather than a UNIQUE index on (node_id, counter):
// sensorPacketCounter is RTC_DATA_ATTR, so it survives deep sleep but RESETS
// TO 0 on power loss. A permanent constraint would silently reject valid
// packets from any node that had been power-cycled.

const WINDOW_MS = 120000;   // ~2 min: far longer than any path's delivery skew

const p = msg.payload || {};
const nodeId = p.nodeId;
const counter = p.counter;

// Anything we cannot key on is passed through rather than dropped: losing real
// data would be worse than storing an occasional duplicate.
if (nodeId === undefined || counter === undefined) {
    node.warn('dedupe: payload missing nodeId/counter, passing through');
    return [msg, null];
}

const key = nodeId + ':' + (p.type || 'sensor') + ':' + counter;
const now = Date.now();
const seen = context.get('seen') || {};

// Prune before the lookup so the object cannot grow without bound.
for (const k in seen) {
    if (now - seen[k] > WINDOW_MS) { delete seen[k]; }
}

if (seen[key] !== undefined) {
    const age = now - seen[key];
    const dropped = (context.get('dropped') || 0) + 1;
    context.set('dropped', dropped);
    context.set('seen', seen);
    node.status({ fill: 'yellow', shape: 'ring', text: 'dropped ' + dropped + ' dup' });
    msg.dedupe = { key: key, ageMs: age, dropped: dropped };
    return [null, msg];
}

seen[key] = now;
context.set('seen', seen);
node.status({ fill: 'green', shape: 'dot', text: 'pass ' + key });
return [msg, null];

payload:
ALTER TABLE digital_pins DROP CONSTRAINT IF EXISTS digital_pins_pin_index_check;
ALTER TABLE digital_pins ADD CONSTRAINT digital_pins_pin_index_check CHECK (pin_index BETWEEN 0 AND 15);

CREATE TABLE IF NOT EXISTS bus_pins (
    id SERIAL PRIMARY KEY,
    device_id INTEGER NOT NULL REFERENCES devices(id) ON DELETE CASCADE,
    pin_index SMALLINT NOT NULL CHECK (pin_index BETWEEN 0 AND 7),
    label VARCHAR(100) DEFAULT "",
    low_threshold NUMERIC,
    high_threshold NUMERIC,
    alert_level VARCHAR(10) DEFAULT "None" CHECK (alert_level IN ("None", "Low", "Medium", "High")),
    UNIQUE(device_id, pin_index)
);

CREATE OR REPLACE FUNCTION create_device_pins()
RETURNS TRIGGER AS $$
BEGIN
    INSERT INTO digital_pins (device_id, pin_index)
    SELECT NEW.id, i FROM generate_series(0, 15) AS i
    ON CONFLICT DO NOTHING;

    INSERT INTO analog_pins (device_id, pin_index)
    SELECT NEW.id, i FROM generate_series(0, 3) AS i
    ON CONFLICT DO NOTHING;

    INSERT INTO bus_pins (device_id, pin_index)
    SELECT NEW.id, i FROM generate_series(0, 7) AS i
    ON CONFLICT DO NOTHING;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

