func:
const user = env.get('NOTIFY_EMAIL_USER');
const pass = env.get('NOTIFY_EMAIL_PASS');

if (!user || !pass) {
    msg.payload = {
        status: 'CONFIG_ERROR',
        message: 'Environment variables NOTIFY_EMAIL_USER or NOTIFY_EMAIL_PASS are missing',
        user_set: !!user,
        pass_set: !!pass
    };
    node.send(msg);
    return null;
}

try {
    const transporter = nodemailer.createTransport({
        host: 'smtp.gmail.com',
        port: 465,
        secure: true,
        auth: { user: user, pass: pass }
    });

    transporter.sendMail({
        from: '"SensorSentinel" <' + user + '>',
        to: 'nolfonzo@gmail.com',
        subject: '[TEST] SensorSentinel Live Verification',
        text: 'This is a live SMTP diagnostic test from SensorSentinel Node-RED on Pi 5.'
    }).then(info => {
        msg.payload = {
            status: 'SUCCESS',
            messageId: info.messageId,
            response: info.response
        };
        node.send(msg);
    }).catch(err => {
        msg.payload = {
            status: 'SMTP_ERROR',
            message: err.message,
            code: err.code,
            response: err.response
        };
        node.send(msg);
    });
} catch(e) {
    msg.payload = { status: 'INIT_ERROR', message: e.message };
    node.send(msg);
}
return null;

const net = global.get("net") || require("net");

const targets = [
    { name: "mosquitto_dns", host: "mosquitto", port: 1883 },
    { name: "postgres_dns", host: "postgres", port: 5432 },
    { name: "pi5_ip_mqtt", host: "192.168.9.77", port: 1883 },
    { name: "docker_gw_mqtt", host: "172.17.0.1", port: 1883 },
    { name: "localhost_mqtt", host: "127.0.0.1", port: 1883 }
];

targets.forEach(target => {
    const sock = new net.Socket();
    sock.setTimeout(2000);
    sock.on("connect", () => {
        node.send({ payload: "CONNECT SUCCESS: " + target.name + " (" + target.host + ":" + target.port + ")" });
        sock.destroy();
    });
    sock.on("error", (err) => {
        node.send({ payload: "CONNECT FAILED: " + target.name + " (" + target.host + ":" + target.port + ") - " + err.message });
    });
    sock.on("timeout", () => {
        node.send({ payload: "CONNECT TIMEOUT: " + target.name + " (" + target.host + ":" + target.port + ")" });
        sock.destroy();
    });
    try {
        sock.connect(target.port, target.host);
    } catch(e) {
        node.send({ payload: "CONNECT EXCEPTION: " + target.name + " - " + e.message });
    }
});

return null;

// A sensor that goes quiet looks exactly like a sensor reporting "all fine",
// so silence has to raise an alarm of its own. Alerts on the transition only,
// so a dead node does not mail every five minutes.
const rows = msg.payload || [];

for (const d of rows) {
    const key = "state_watchdog_" + d.device_id;
    const prev = flow.get(key) || "ALIVE";
    const now = d.is_stale ? "SILENT" : "ALIVE";
    if (now === prev) { continue; }
    flow.set(key, now);

    const mins = d.silent_minutes;
    const human = mins >= 1440 ? Math.round(mins / 1440) + " days"
                : mins >= 60   ? Math.round(mins / 60) + " hours"
                :                mins + " minutes";

    const alert = {
        deviceId: d.device_id,
        ownerName: d.owner_name || "nolfonzo",
        ownerEmail: d.owner_email || "nolfonzo@gmail.com",
        notifyVia: d.notify_via || "email",
        ownerMuted: d.owner_muted === true,
        deviceName: d.display_name,
        nodeId: d.node_id,
        pinLabel: "Device Offline",
        state: now,
        alertMessage: now === "SILENT"
            ? ("NO CONTACT: no packet received for " + human +
               " (threshold: " + d.stale_after_minutes + " min). The node may have a flat " +
               "battery, water ingress, or a radio/gateway fault - its sensors are NOT being monitored.")
            : ("RESOLVED: device is reporting again after " + human + " of silence"),
        alertLevel: now === "SILENT" ? "High" : "Info",
        action: now === "SILENT" ? "TRIGGERED" : "RESOLVED",
    };

    node.send({
        query: "INSERT INTO alerts (device_id, pin_label, alert_message, alert_level) VALUES ($1, $2, $3, $4) ON CONFLICT (device_id, pin_label) DO UPDATE SET alert_message = EXCLUDED.alert_message, alert_level = EXCLUDED.alert_level, count = alerts.count + 1, updated_at = NOW()",
        params: [alert.deviceId, alert.pinLabel, alert.alertMessage, alert.alertLevel],
        payload: "",
        alert: alert,
    });
    node.warn("watchdog: " + d.display_name + " -> " + now + " (" + human + ")");
}
return null;

// Poll Telegram for commands.
//
// Deliberately plain HTTP rather than node-red-contrib-telegrambot: that node
// keeps the token in Node-RED's credential store, which means re-pasting it by
// hand in the editor every time this stack is rebuilt. Read from the
// environment, the bot is recreatable from .env like everything else here.

const token = env.get('TELEGRAM_BOT_TOKEN');
if (!token) {
    node.status({ fill: 'grey', shape: 'ring', text: 'TELEGRAM_BOT_TOKEN not set' });
    return null;
}

// Never let two polls overlap: a slow reply would otherwise be re-requested at
// the same offset and every command would run twice.
//
// Time-bounded on purpose. A plain boolean flag wedges permanently if a poll
// throws between setting and clearing it - every later poll then returns here
// silently, with no error to explain the silence, and because context persists
// to disk not even a restart recovers. Ask how long it has been held instead.
const HELD_MS = 30000;
const heldSince = context.get('pollHeldSince') || 0;
if (heldSince && (Date.now() - heldSince) < HELD_MS) return null;
context.set('pollHeldSince', Date.now());
const done = () => context.set('pollHeldSince', 0);

// Telegram API calls go through Node's https module, not fetch. Node-RED runs
// function nodes in a vm context that does not inherit the global fetch, so it
// is undefined here even on Node 20 - the same trap as globalThis.crypto.
const tgApi = (method, body) => new Promise((resolve, reject) => {
    const data = body ? JSON.stringify(body) : null;
    const req = https.request({
        hostname: 'api.telegram.org',
        // Force IPv4. DNS returns an AAAA record for api.telegram.org, this
        // container has no working IPv6 route, and Node tries v6 first - which
        // surfaces as an AggregateError wrapping ETIMEDOUT rather than
        // anything that names the real problem. curl worked here all along
        // because it falls back to v4 by itself.
        family: 4,
        path: '/bot' + token + '/' + method,
        method: body ? 'POST' : 'GET',
        headers: body ? { 'Content-Type': 'application/json',
                          'Content-Length': Buffer.byteLength(data) } : {}
    }, res => {
        let out = '';
        res.setEncoding('utf8');
        res.on('data', c => out += c);
        res.on('end', () => {
            try { resolve(JSON.parse(out)); }
            catch (e) { reject(new Error('non-JSON reply: ' + out.slice(0, 120))); }
        });
    });
    req.on('error', reject);
    if (data) req.write(data);
    req.end();
});


// Learn the bot's own username, and keep Telegram's command menu in step with
// what the router actually understands.
//
// This used to run only when the username was unknown, which meant it fired
// once ever - so every command added afterwards was missing from the menu while
// working perfectly if typed. Keyed on the command list itself now, so changing
// the list is enough to republish it.
const COMMANDS = [
    { command: 'status',     description: 'Last reading from your devices' },
    { command: 'sensors',    description: 'Every channel and what it reads now' },
    { command: 'watch',      description: 'Every reading as it arrives' },
    { command: 'unwatch',    description: 'Stop all feeds' },
    { command: 'info',       description: 'What you own and how it is set up' },
    { command: 'sensorname', description: 'Name a channel, e.g. /sensorname D5 Bilge' },
    { command: 'sensoralert', description: 'When a switch should alert you' },
    { command: 'limits',     description: 'Alert outside a range, e.g. /limits bus0 12000 14500' },
    { command: 'claim',      description: 'Take on a device (code is on its screen)' },
    { command: 'alerts',     description: 'Where your alerts go' },
    { command: 'email',      description: 'Turn email alerts on or off' },
    { command: 'mute',       description: 'Silence all alerts, e.g. /mute 2h' },
    { command: 'unmute',     description: 'Start receiving alerts again' },
    { command: 'help',       description: 'What I can do' }
];
const cmdSig = COMMANDS.map(c => c.command).join(',');

if (!global.get('tgBotUsername') || global.get('tgCommandsSig') !== cmdSig) {
    tgApi('getMe')
        .then(j => {
            if (j.ok && j.result && j.result.username) {
                global.set('tgBotUsername', j.result.username);
            }
            return tgApi('setMyCommands', { commands: COMMANDS });
        })
        .then(j => { if (j && j.ok) global.set('tgCommandsSig', cmdSig); })
        .catch(() => {});
}

const offset = context.get('offset');

// First poll after a restart: discard the backlog instead of replaying it.
// Telegram holds undelivered updates for 24h, so without this every command
// sent since yesterday would re-execute on startup.
const first = (offset === undefined);
tgApi('getUpdates?timeout=0&offset=' + (first ? -1 : offset)).then(j => {
    done();
    if (!j.ok) {
        node.status({ fill: 'red', shape: 'ring', text: 'getUpdates failed' });
        node.error('getUpdates: ' + JSON.stringify(j).slice(0, 200));
        return;
    }

    if (first) {
        const last = j.result.length ? j.result[j.result.length - 1].update_id + 1 : 0;
        context.set('offset', last);
        node.status({ fill: 'green', shape: 'ring',
                      text: 'ready (discarded ' + j.result.length + ' backlog)' });
        return;
    }

    let n = 0;
    for (const u of j.result) {
        // Advance before handling: a command that throws must not be redelivered
        // for ever on every subsequent poll.
        context.set('offset', u.update_id + 1);

        const cb = u.callback_query;
        const m  = u.message;
        let tg = null;

        if (cb && cb.message) {
            tg = { chatId: cb.message.chat.id, text: String(cb.data || ''),
                   fromName: (cb.from && cb.from.first_name) || 'there',
                   callbackId: cb.id, isCallback: true };
        } else if (m && typeof m.text === 'string') {
            tg = { chatId: m.chat.id, text: m.text.trim(),
                   fromName: (m.from && m.from.first_name) || 'there',
                   isCallback: false };
        } else {
            continue;   // stickers, joins, edits - nothing to do
        }

        n++;
        node.send({ tg: tg });
    }
    node.status({ fill: 'green', shape: 'dot', text: 'polling' + (n ? ' (+' + n + ')' : '') });
}).catch(e => {
    done();
    node.status({ fill: 'red', shape: 'ring', text: 'poll error' });
    node.error('getUpdates: ' + (e && (e.message || e.code) ? (e.message || e.code) : String(e)));
});

return null;

// Who is this chat? Everything downstream is scoped by the answer, so an
// unrecognised chat can only ever reach the pairing path.
msg.query = `SELECT o.id, o.name, o.email, o.notify_via, o.is_admin,
                    o.telegram_chat_id,
                    (SELECT count(*) FROM devices d WHERE d.owner_id = o.id) AS device_count
             FROM owners o
             WHERE o.telegram_chat_id = $1`;
msg.params = [String(msg.tg.chatId)];
return msg;

// The single exit to Telegram - alerts, digests and command replies all leave
// through here.
//
// No parse_mode. Markdown would render a little more nicely, but Telegram
// rejects the whole message if an interpolated device name contains a stray
// underscore or asterisk, and a boat called "Renko_2" silently costing someone
// an alert is not a trade worth making.

const token = env.get('TELEGRAM_BOT_TOKEN');
if (!token) { node.error('TELEGRAM_BOT_TOKEN not set - cannot send'); return null; }

// Telegram API calls go through Node's https module, not fetch. Node-RED runs
// function nodes in a vm context that does not inherit the global fetch, so it
// is undefined here even on Node 20 - the same trap as globalThis.crypto.
const tgApi = (method, body) => new Promise((resolve, reject) => {
    const data = body ? JSON.stringify(body) : null;
    const req = https.request({
        hostname: 'api.telegram.org',
        // Force IPv4. DNS returns an AAAA record for api.telegram.org, this
        // container has no working IPv6 route, and Node tries v6 first - which
        // surfaces as an AggregateError wrapping ETIMEDOUT rather than
        // anything that names the real problem. curl worked here all along
        // because it falls back to v4 by itself.
        family: 4,
        path: '/bot' + token + '/' + method,
        method: body ? 'POST' : 'GET',
        headers: body ? { 'Content-Type': 'application/json',
                          'Content-Length': Buffer.byteLength(data) } : {}
    }, res => {
        let out = '';
        res.setEncoding('utf8');
        res.on('data', c => out += c);
        res.on('end', () => {
            try { resolve(JSON.parse(out)); }
            catch (e) { reject(new Error('non-JSON reply: ' + out.slice(0, 120))); }
        });
    });
    req.on('error', reject);
    if (data) req.write(data);
    req.end();
});


// Stop the spinner on a tapped button, whatever else happens next.
if (msg.tgCallbackId) {
    tgApi('answerCallbackQuery', { callback_query_id: msg.tgCallbackId }).catch(() => {});
}

const chatId = msg.tgChatId;
const text   = msg.tgText;
if (!chatId || !text) return null;

// Telegram hard-rejects messages over 4096 characters. Trim rather than let a
// long /info disappear behind an opaque API error.
let outText = text;
if (outText.length > 3900) outText = outText.slice(0, 3880) + '\n... (trimmed)';

const body = { chat_id: chatId, text: outText, disable_web_page_preview: true };
if (msg.tgButtons) body.reply_markup = { inline_keyboard: msg.tgButtons };

tgApi('sendMessage', body).then(j => {
    if (!j.ok) {
        node.error('sendMessage: ' + JSON.stringify(j).slice(0, 300));
        node.status({ fill: 'red', shape: 'ring', text: 'send failed' });
    } else {
        node.status({ fill: 'green', shape: 'dot', text: 'sent -> ' + chatId });
    }
}).catch(e => node.error('sendMessage: ' + e.message));

return null;

// Route a Telegram command. Everything is scoped to what this chat owns; an
// admin sees every device. Output 1 is a query tagged with msg.tgAction,
// output 2 a reply that needs no database round trip.

const tg    = msg.tg;
const rows  = msg.payload || [];
const owner = rows.length ? rows[0] : null;
const raw   = String(tg.text || '').trim();

const CLAIM_SQL = `WITH target AS (
    -- Only an unowned device can be claimed. One that already belongs to
    -- someone must be released by them first, so possession of the code can
    -- never take a boat off its owner.
    SELECT id, display_name, node_id
      FROM devices
     WHERE owner_id IS NULL
       AND lpad(to_hex(node_id & 16777215), 6, '0') = lower($1::text)
     LIMIT 1
), existing AS (
    SELECT id, name FROM owners WHERE telegram_chat_id = $2::bigint
), created AS (
    -- An unpaired chat with a valid code becomes an owner on the spot: no
    -- email, no invitation, no admin. Email left NULL deliberately - adding one
    -- later fires the re-welcome trigger and introduces the system properly.
    INSERT INTO owners (name, telegram_chat_id, notify_via)
    SELECT $3::text, $2::bigint, 'telegram'
     WHERE EXISTS (SELECT 1 FROM target)
       AND NOT EXISTS (SELECT 1 FROM existing)
    RETURNING id, name
), resolved AS (
    SELECT id, name FROM existing
    UNION ALL
    SELECT id, name FROM created
)
UPDATE devices d
   SET owner_id = (SELECT id FROM resolved LIMIT 1),
       -- A device nobody has named yet is called Node-33676358 by
       -- auto-registration, which means nothing to a person. Let the claimer
       -- name it in the same breath; keep the existing name if they do not.
       display_name = COALESCE(NULLIF($4::text, ''), d.display_name),
       updated_at = NOW()
 WHERE d.id IN (SELECT id FROM target)
RETURNING d.display_name, d.node_id,
          upper(lpad(to_hex(d.node_id & 16777215), 6, '0')) AS claim_code,
          (d.display_name LIKE 'Node-%') AS unnamed,
          (SELECT name FROM resolved LIMIT 1) AS owner_name`;

const RENAME_SQL = `WITH scope AS (
    SELECT d.id, d.display_name, d.node_id
      FROM devices d
     WHERE ($2::boolean OR d.owner_id = $1::int)
)
UPDATE devices
   SET display_name = $4::text, updated_at = NOW()
 WHERE id IN (SELECT id FROM scope
               WHERE lower(display_name) LIKE '%' || lower($3::text) || '%'
                  OR node_id::text = $3::text
                  -- the claim code works as an identifier too: it is what they
                  -- just read off the screen and typed
                  OR lpad(to_hex(node_id & 16777215), 6, '0') = lower($3::text))
RETURNING display_name`;

const RELEASE_SQL = `WITH scope AS (
    SELECT d.id, d.display_name, d.node_id
      FROM devices d
     WHERE ($2::boolean OR d.owner_id = $1::int)
)
UPDATE devices
   SET owner_id = NULL, verbose_until = NULL, verbose_chat_id = NULL, updated_at = NOW()
 WHERE id IN (SELECT id FROM scope
               WHERE lower(display_name) LIKE '%' || lower($3::text) || '%'
                  OR node_id::text = $3::text)
RETURNING display_name, upper(lpad(to_hex(node_id & 16777215), 6, '0')) AS claim_code`;

const reply = (text, buttons) => ({
    tgChatId: tg.chatId, tgText: text,
    tgButtons: buttons || null, tgCallbackId: tg.callbackId || null
});

// A pairing token grants access to someone's devices, so not Math.random.
// Alphabet excludes I/O/0/1 so it survives being read aloud or retyped.
const mkToken = () => {
    const abc = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    // Node's crypto module, not globalThis.crypto - Node-RED runs function
    // nodes in a vm context that does not inherit Web Crypto, so the global is
    // undefined here even on Node 20.
    const buf = nodeCrypto.randomBytes(16);
    let out = '';
    for (let i = 0; i < 16; i++) out += abc[buf[i] % abc.length];
    return out;
};

// ── unpaired chats may only redeem a token ──────────────────────────────────
// Matched on the raw text, not a lowercased copy: tokens are case sensitive.
if (!owner) {
    const m = raw.match(/^\/?(?:start|pair)\s+(\S+)$/i);
    if (m) {
        msg.tgAction = 'pair';
        msg.query = `UPDATE owners
                        SET telegram_chat_id = $1, pair_code = NULL, updated_at = NOW()
                      WHERE pair_code = $2
                  RETURNING id, name, notify_via,
                            (SELECT count(*) FROM devices d WHERE d.owner_id = owners.id) AS device_count`;
        msg.params = [String(tg.chatId), m[1]];
        return [msg, null];
    }
    // Claiming works from an unrecognised chat on purpose: hold the device,
    // read the six characters off its screen, and you are in the system.
    const c = raw.match(/^\/?claim\s+([0-9a-fA-F]{6})(?:\s+(.+))?$/);
    if (c) {
        msg.tgAction = 'claim';
        msg.query = CLAIM_SQL;
        msg.params = [c[1], String(tg.chatId), tg.fromName || 'New owner',
                      (c[2] || '').trim()];
        return [msg, null];
    }

    return [null, reply(
        "I don't recognise this chat yet.\n\n" +
        'Open the link in your SensorSentinel email - it connects you in one tap.\n\n' +
        'Setting up a new device? Press its button and send me the six\n' +
        'characters shown on its screen:\n    /claim 676358'
    )];
}

const isAdmin = owner.is_admin === true;
msg.tgOwner = owner;          // the formatter needs it after payload is replaced

const WATCH_MINS = 30;        // watches expire; /unwatch is the fast path, this
                              // is the catch for when you have walked away

let cmd, arg = null, mins = WATCH_MINS;

// ── buttons ─────────────────────────────────────────────────────────────────
if (tg.isCallback) {
    const c = String(tg.text || '').toLowerCase();
    let m;
    if (c === 'status')                              { cmd = 'status'; }
    else if (c === 'unwatch')                        { cmd = 'unwatch'; }
    else if (c === 'unmute')                         { cmd = 'unmute'; }
    else if ((m = c.match(/^watch:(\d+):(\d+)$/)))   { cmd = 'watch'; arg = m[1]; mins = Number(m[2]); }
    else if ((m = c.match(/^off:(\d+)$/)))            { cmd = 'unwatch'; arg = m[1]; }
    else if ((m = c.match(/^notify:(here|email|both)$/))) {
        msg.tgAction = 'notify';
        msg.query = `UPDATE owners SET notify_via = $2, updated_at = NOW()
                      WHERE id = $1 RETURNING name, notify_via`;
        msg.params = [owner.id, m[1] === 'here' ? 'telegram' : m[1]];
        return [msg, null];
    }
    else { cmd = 'help'; }
}

// ── typed commands ──────────────────────────────────────────────────────────
if (!cmd) {
    const parts = raw.split(/\s+/);
    cmd = (parts[0] || '').toLowerCase().replace(/^\//, '');
    const rest = parts.slice(1);
    // A trailing number on /watch is a duration; the rest is a device name.
    if ((cmd === 'watch' || cmd === 'verbose') && rest.length && /^\d+$/.test(rest[rest.length - 1])) {
        mins = Number(rest.pop());
    }
    arg = rest.join(' ').trim() || null;
    if (raw === '/' || cmd === '') cmd = 'help';
}

// Bounded: this is the switch that messages you every 30 seconds.
mins = Math.max(1, Math.min(480, mins));

const PINS = `json_agg(DISTINCT jsonb_build_object('pin_index', dp.pin_index, 'label', dp.label, 'trigger', dp.trigger, 'alert_level', dp.alert_level))
                      FILTER (WHERE dp.label <> '') AS digital_pins,
                    json_agg(DISTINCT jsonb_build_object('pin_index', ap.pin_index, 'label', ap.label,
                             'low_threshold', ap.low_threshold, 'high_threshold', ap.high_threshold, 'alert_level', ap.alert_level))
                      FILTER (WHERE ap.label <> '') AS analog_pins,
                    json_agg(DISTINCT jsonb_build_object('pin_index', bp.pin_index, 'label', bp.label,
                             'low_threshold', bp.low_threshold, 'high_threshold', bp.high_threshold, 'alert_level', bp.alert_level))
                      FILTER (WHERE bp.label <> '') AS bus_pins`;
const JOINS = `FROM devices d
               LEFT JOIN digital_pins dp ON dp.device_id = d.id
               LEFT JOIN analog_pins  ap ON ap.device_id = d.id
               LEFT JOIN bus_pins     bp ON bp.device_id = d.id`;
const SCOPE = `WHERE ($2::boolean OR d.owner_id = $1::int)
                AND ($3::text IS NULL
                     OR lower(d.display_name) LIKE '%' || lower($3::text) || '%'
                     OR d.node_id::text = $3::text)`;

switch (cmd) {

case 'status':
    msg.tgAction = 'status';
    msg.query = `SELECT d.id, d.display_name, d.node_id, d.last_seen,
                        (d.verbose_until > NOW()) AS verbose_active,
                        GREATEST(0, EXTRACT(EPOCH FROM (d.verbose_until - NOW()))::int) AS verbose_secs_left,
                        EXTRACT(EPOCH FROM (NOW() - d.last_seen)) AS age_sec,
                        (SELECT e.payload FROM events e
                          WHERE e.device_id = d.id ORDER BY e.id DESC LIMIT 1) AS last_payload,
                        ${PINS}
                 ${JOINS}
                 ${SCOPE}
               GROUP BY d.id
               ORDER BY d.display_name`;
    msg.params = [owner.id, isAdmin, arg];
    return [msg, null];

case 'sensoralert':
case 'trigger': {
    const bits = (arg || '').trim().split(/\s+/).filter(Boolean);
    if (bits.length < 2) {
        return [null, reply('Which switch, and when should it alert?\n' +
                            '    /sensoralert D5 open     alert when it opens\n' +
                            '    /sensoralert D5 closed   alert when it closes\n' +
                            '    /sensoralert D5 change   tell me either way\n' +
                            '    /sensoralert D5 off      say nothing\n\n' +
                            '/sensors shows which are open right now.')];
    }
    let device = null;
    if (!/^d\d+$/i.test(bits[0])) device = bits.shift();
    const chan = bits.shift() || '';
    const m = chan.match(/^d(\d+)$/i);
    if (!m) return [null, reply('This one is for the switch inputs, D0 to D7.\nFor a battery, /limits is what you want.')];
    const idx = Number(m[1]);
    if (idx > 7) return [null, reply('There are only eight inputs, D0 to D7.')];

    // open/closed rather than high/low: an input reads 1 when nothing pulls it
    // down, which is what "open" means on a switch. high/low still accepted.
    const MAP = { open:'High', high:'High', '1':'High',
                  closed:'Low', close:'Low', low:'Low', '0':'Low',
                  change:'Change', both:'Change', either:'Change',
                  off:'None', none:'None', never:'None' };
    const word = (bits.shift() || '').toLowerCase();
    const trig = MAP[word];
    if (!trig) return [null, reply('"' + word + '"? I understand open, closed, change or off.')];

    msg.tgAction = 'sensoralert';
    msg.query = `WITH scope AS (
                    SELECT d.id, d.display_name FROM devices d
                     WHERE ($2::boolean OR d.owner_id = $1::int)
                       AND ($3::text IS NULL
                            OR lower(d.display_name) LIKE '%' || lower($3::text) || '%'
                            OR d.node_id::text = $3::text
                            OR lpad(to_hex(d.node_id & 16777215), 6, '0') = lower($3::text))
                 ), pick AS (
                    SELECT id, display_name FROM scope
                     WHERE $3::text IS NOT NULL OR (SELECT count(*) FROM scope) = 1
                     LIMIT 1
                 )
                 UPDATE digital_pins t
                    SET trigger = $4::text,
                        -- Set with the trigger, so an armed pin never sits at
                        -- severity 'None' and quietly does nothing.
                        alert_level = CASE WHEN $4::text = 'None' THEN 'None' ELSE 'High' END
                  WHERE t.device_id IN (SELECT id FROM pick) AND t.pin_index = $5::int
              RETURNING (SELECT display_name FROM pick) AS device_name,
                        t.pin_index, t.label, t.trigger`;
    msg.params = [owner.id, isAdmin, device, trig, idx];
    return [msg, null];
}

case 'limits':
case 'threshold':
case 'thresholds': {
    const bits = (arg || '').trim().split(/\s+/).filter(Boolean);
    if (bits.length < 2) {
        return [null, reply('Which channel, and what limits?\n' +
                            '    /limits bus0 12000 14500   alert outside this range\n' +
                            '    /limits bus0 12000         low limit only\n' +
                            '    /limits bus0 off           stop alerting\n\n' +
                            'Check /sensors first - set the limit in the same units\n' +
                            'as the number it actually reads.')];
    }
    let device = null;
    if (!/^(bus|a)\d+$/i.test(bits[0])) device = bits.shift();
    const chan = bits.shift() || '';
    const m = chan.match(/^(bus|a)(\d+)$/i);
    if (!m) return [null, reply('This one is for bus and analog channels, like bus0 or A2.\nFor a switch, /sensoralert is what you want.')];
    const kind = m[1].toLowerCase();
    const idx  = Number(m[2]);
    const table  = kind === 'bus' ? 'bus_pins' : 'analog_pins';
    const maxIdx = kind === 'bus' ? 7 : 3;
    if (idx > maxIdx) return [null, reply(chan.toUpperCase() + ' does not exist.')];

    let lo = null, hi = null;
    const first = (bits[0] || '').toLowerCase();
    if (!['off','none','never'].includes(first)) {
        const nums = bits.filter(x => /^-?\d+(\.\d+)?$/.test(x)).map(Number);
        if (!nums.length) return [null, reply('I need a number.   /limits ' + chan + ' 12000 14500')];
        lo = nums[0];
        if (nums.length > 1) hi = nums[1];
        if (lo !== null && hi !== null && lo > hi) { const t = lo; lo = hi; hi = t; }
    }

    msg.tgAction  = 'limits';
    msg.tgKind    = kind;
    msg.tgIndex   = idx;
    msg.tgChannel = chan.toUpperCase();
    msg.query = `WITH scope AS (
                    SELECT d.id, d.display_name FROM devices d
                     WHERE ($2::boolean OR d.owner_id = $1::int)
                       AND ($3::text IS NULL
                            OR lower(d.display_name) LIKE '%' || lower($3::text) || '%'
                            OR d.node_id::text = $3::text
                            OR lpad(to_hex(d.node_id & 16777215), 6, '0') = lower($3::text))
                 ), pick AS (
                    SELECT id, display_name FROM scope
                     WHERE $3::text IS NOT NULL OR (SELECT count(*) FROM scope) = 1
                     LIMIT 1
                 )
                 UPDATE ` + table + ` t
                    SET low_threshold = $4::numeric,
                        high_threshold = $5::numeric,
                        alert_level = CASE WHEN $4::numeric IS NULL AND $5::numeric IS NULL
                                           THEN 'None' ELSE 'High' END
                  WHERE t.device_id IN (SELECT id FROM pick) AND t.pin_index = $6::int
              RETURNING (SELECT display_name FROM pick) AS device_name,
                        t.pin_index, t.label, t.low_threshold, t.high_threshold, t.alert_level,
                        -- The last reading comes back with it so the reply can
                        -- show the limit next to the number it will be compared
                        -- against. Setting 12 against a value of 13008 is the
                        -- units mistake this is here to make obvious.
                        (SELECT e.payload FROM events e
                          WHERE e.device_id IN (SELECT id FROM pick)
                          ORDER BY e.id DESC LIMIT 1) AS last_payload`;
    msg.params = [owner.id, isAdmin, device, lo, hi, idx];
    return [msg, null];
}

case 'sensorname':
case 'label': {
    const bits = (arg || '').trim().split(/\s+/).filter(Boolean);
    if (bits.length < 2) {
        return [null, reply('Which channel, and what should I call it?\n' +
                            '    /sensorname D5 Bilge float\n' +
                            '    /sensorname bus1 Aux battery\n\n' +
                            'Run /sensors to see what channels there are.')];
    }

    // Optional leading device, for when you own more than one:
    //   /name renko D5 Bilge float
    let device = null;
    if (!/^(bus|a|d)\d+$/i.test(bits[0])) device = bits.shift();

    const chan = bits.shift() || '';
    const m = chan.match(/^(bus|a|d)(\d+)$/i);
    if (!m) {
        return [null, reply('I did not recognise "' + chan + '".\n' +
                            'Channels look like bus1, A2 or D5 - /sensors lists them.')];
    }
    const label = bits.join(' ').trim();
    if (!label) return [null, reply('What should I call it?\n    /sensorname ' + chan + ' Bilge float')];

    const kind = m[1].toLowerCase();
    const idx  = Number(m[2]);
    // Table chosen from a fixed set, never from user text.
    const table  = kind === 'bus' ? 'bus_pins' : kind === 'a' ? 'analog_pins' : 'digital_pins';
    const maxIdx = kind === 'a' ? 3 : 7;
    if (idx > maxIdx) {
        return [null, reply(chan.toUpperCase() + ' does not exist - ' +
                            (kind === 'a' ? 'analog goes A0 to A3.'
                                          : (kind === 'bus' ? 'bus goes bus0 to bus7.'
                                                            : 'there are only eight inputs, D0 to D7.')))];
    }

    msg.tgAction  = 'name';
    msg.tgChannel = chan.toUpperCase();
    msg.tgKind    = kind;
    msg.query = `WITH scope AS (
                    SELECT d.id, d.display_name FROM devices d
                     WHERE ($2::boolean OR d.owner_id = $1::int)
                       AND ($3::text IS NULL
                            OR lower(d.display_name) LIKE '%' || lower($3::text) || '%'
                            OR d.node_id::text = $3::text
                            OR lpad(to_hex(d.node_id & 16777215), 6, '0') = lower($3::text))
                 ), pick AS (
                    -- With no device named, this only resolves if they own
                    -- exactly one. Otherwise it returns nothing and the reply
                    -- asks which, rather than labelling the wrong boat.
                    SELECT id, display_name FROM scope
                     WHERE $3::text IS NOT NULL OR (SELECT count(*) FROM scope) = 1
                     LIMIT 1
                 )
                 UPDATE ` + table + ` t
                    SET label = $4::text
                  WHERE t.device_id IN (SELECT id FROM pick)
                    AND t.pin_index = $5::int
              RETURNING (SELECT display_name FROM pick) AS device_name,
                        t.pin_index, t.label`;
    msg.params = [owner.id, isAdmin, device, label, idx];
    return [msg, null];
}

case 'sensors':
case 'channels':
    msg.tgAction = 'sensors';
    // Deliberately unfiltered, unlike /status and /info. This is the view that
    // answers "I just plugged something in - did it land?", so a channel with
    // no label is exactly what it needs to show.
    msg.query = `SELECT d.display_name, d.node_id,
                        EXTRACT(EPOCH FROM (NOW() - d.last_seen)) AS age_sec,
                        (SELECT e.payload FROM events e
                          WHERE e.device_id = d.id ORDER BY e.id DESC LIMIT 1) AS last_payload,
                        json_agg(DISTINCT jsonb_build_object('pin_index', dp.pin_index,
                                 'label', dp.label, 'trigger', dp.trigger,
                                 'alert_level', dp.alert_level)) AS digital_pins,
                        json_agg(DISTINCT jsonb_build_object('pin_index', ap.pin_index,
                                 'label', ap.label, 'low_threshold', ap.low_threshold,
                                 'high_threshold', ap.high_threshold,
                                 'alert_level', ap.alert_level)) AS analog_pins,
                        json_agg(DISTINCT jsonb_build_object('pin_index', bp.pin_index,
                                 'label', bp.label, 'low_threshold', bp.low_threshold,
                                 'high_threshold', bp.high_threshold,
                                 'alert_level', bp.alert_level)) AS bus_pins
                 ${JOINS}
                 ${SCOPE}
               GROUP BY d.id
               ORDER BY d.display_name`;
    msg.params = [owner.id, isAdmin, arg];
    return [msg, null];

case 'info':
    msg.tgAction = 'info';
    msg.query = `SELECT d.display_name, d.node_id, d.stale_after_minutes, d.watchdog_enabled,
                        ${PINS}
                 ${JOINS}
                 ${SCOPE}
               GROUP BY d.id
               ORDER BY d.display_name`;
    msg.params = [owner.id, isAdmin, arg];
    return [msg, null];

case 'watch':
case 'verbose':
    msg.tgAction = 'watch';
    msg.query = `UPDATE devices d
                    SET verbose_until = NOW() + make_interval(mins => $4::int),
                        verbose_chat_id = $5::bigint, updated_at = NOW()
                  ${SCOPE}
              RETURNING display_name, node_id,
                        GREATEST(0, EXTRACT(EPOCH FROM (verbose_until - NOW()))::int) AS verbose_secs_left`;
    msg.params = [owner.id, isAdmin, arg, mins, String(tg.chatId)];
    return [msg, null];

case 'unwatch':
case 'stop':
case 'off':
    msg.tgAction = 'unwatch';
    if (arg) {
        // Named a device - or tapped Stop on one device's digest, which means
        // "this one", matching the Another 30m button sitting beside it.
        msg.query = `WITH scope AS (
                        SELECT d.id, d.node_id, d.display_name
                          FROM devices d
                         WHERE ($2::boolean OR d.owner_id = $1::int)
                     )
                     UPDATE devices
                        SET verbose_until = NULL, verbose_chat_id = NULL, updated_at = NOW()
                      WHERE id IN (SELECT id FROM scope
                                    WHERE lower(display_name) LIKE '%' || lower($3::text) || '%'
                                       OR node_id::text = $3::text)
                  RETURNING display_name`;
        msg.params = [owner.id, isAdmin, arg];
    } else {
        // Bare /unwatch stops the lot. Also clears anything this chat started on
        // someone else's device, so an admin who went looking can always call
        // their own feeds off.
        msg.query = `UPDATE devices d
                        SET verbose_until = NULL, verbose_chat_id = NULL, updated_at = NOW()
                      WHERE d.verbose_until IS NOT NULL
                        AND (d.verbose_chat_id = $3::bigint OR d.owner_id = $1::int OR $2::boolean)
                  RETURNING display_name`;
        msg.params = [owner.id, isAdmin, String(tg.chatId)];
    }
    return [msg, null];

case 'claim': {
    // /claim <code> [name] - naming inline saves a second round trip.
    const bits = (arg || '').trim().split(/\s+/);
    const code = (bits.shift() || '').trim();
    const name = bits.join(' ').trim();
    if (!/^[0-9a-fA-F]{6}$/.test(code)) {
        return [null, reply('Press the button on the device and send me the six\n' +
                            'characters on its screen:\n    /claim 676358\n\n' +
                            'You can name it at the same time:\n    /claim 676358 Renko')];
    }
    msg.tgAction = 'claim';
    msg.query = CLAIM_SQL;
    msg.params = [code, String(tg.chatId), tg.fromName || owner.name, name];
    return [msg, null];
}

case 'rename':
case 'name': {
    const bits = (arg || '').trim().split(/\s+/);
    const which = (bits.shift() || '').trim();
    const to = bits.join(' ').trim();
    if (!which || !to) {
        return [null, reply('Which device, and what should I call it?\n' +
                            '    /rename 676358 Renko')];
    }
    msg.tgAction = 'rename';
    msg.query = RENAME_SQL;
    msg.params = [owner.id, isAdmin, which, to];
    return [msg, null];
}

case 'release':
case 'transfer': {
    if (!arg) return [null, reply('Which device?   /release Renko')];
    msg.tgAction = 'release';
    msg.query = RELEASE_SQL;
    msg.params = [owner.id, isAdmin, arg];
    return [msg, null];
}

case 'mute': {
    // Bare /mute is indefinite; a duration is better, and the reply nudges that
    // way. Silencing a bilge alarm "just for now" is the intention that gets
    // forgotten about.
    const w = (arg || '').trim().toLowerCase();
    let interval = '100 years';
    if (w) {
        const mm = w.match(/^(\d+)\s*(m|min|mins|minutes|h|hr|hrs|hours|d|day|days)?$/);
        if (!mm) return [null, reply('How long?\n    /mute 2h\n    /mute 30m\n    /mute 1d\n    /mute        (until you unmute)')];
        const u = (mm[2] || 'm')[0];
        interval = mm[1] + (u === 'h' ? ' hours' : u === 'd' ? ' days' : ' minutes');
    }
    msg.tgAction = 'mute';
    msg.query = `UPDATE owners
                    SET muted_until = NOW() + ($2::text)::interval, updated_at = NOW()
                  WHERE id = $1
              RETURNING name, notify_via,
                        ($2::text = '100 years') AS indefinite,
                        GREATEST(0, EXTRACT(EPOCH FROM (muted_until - NOW()))::bigint) AS secs_left`;
    msg.params = [owner.id, interval];
    return [msg, null];
}

case 'unmute': {
    msg.tgAction = 'unmute';
    msg.query = `UPDATE owners SET muted_until = NULL, updated_at = NOW()
                  WHERE id = $1 RETURNING name, notify_via`;
    msg.params = [owner.id];
    return [msg, null];
}

case 'email': {
    const w = (arg || '').trim().toLowerCase();
    if (w !== 'on' && w !== 'off') {
        return [null, reply('Email is currently ' +
                (['email','both'].includes(owner.notify_via) ? 'ON' : 'OFF') + '.\n\n' +
                '    /email on     also send alerts by email\n' +
                '    /email off    stop emailing me')];
    }
    const paired = owner.telegram_chat_id !== null && owner.telegram_chat_id !== undefined;

    // Refuse to leave someone with no channel at all. Turning off the only way
    // of reaching you is not a preference, it is a silent alarm - and silence
    // is the one failure this system must never have.
    if (w === 'off' && !paired) {
        return [null, reply('That would leave nowhere to send your alerts.\n\n' +
                            'Email is all I have for you at the moment. Pair this chat\n' +
                            'first and then email can be turned off.')];
    }
    const next = (w === 'on') ? (paired ? 'both' : 'email') : 'telegram';
    msg.tgAction = 'notify';
    msg.query = `UPDATE owners SET notify_via = $2, updated_at = NOW()
                  WHERE id = $1 RETURNING name, notify_via`;
    msg.params = [owner.id, next];
    return [msg, null];
}

case 'alerts':
    return [null, reply(
        'Alerts currently go to: ' + owner.notify_via + '\n\nWhere would you like them?',
        [[{ text: 'Here', callback_data: 'notify:here' },
          { text: 'Email', callback_data: 'notify:email' },
          { text: 'Both', callback_data: 'notify:both' }]]
    )];

case 'invite': {
    if (!isAdmin) return [null, reply('That one is admin only.')];
    if (!arg) return [null, reply('Who for?   /invite DangarStu')];
    msg.tgAction = 'invite';
    msg.query = `UPDATE owners SET pair_code = $2, updated_at = NOW()
                  WHERE lower(name) = lower($1) AND telegram_chat_id IS NULL
              RETURNING name, pair_code`;
    msg.params = [arg, mkToken()];
    return [msg, null];
}

case 'help':
case 'start':
    return [null, reply(
        'SensorSentinel - hello ' + owner.name + '.\n\n' +
        '/status            last reading from every device you own\n' +
        '/status big boat   just that one\n' +
        '/watch             every reading as it arrives, for ' + WATCH_MINS + ' min\n' +
        '/watch big boat    just that one\n' +
        '/unwatch           stop all feeds\n' +
        '/info              what you own and how it is configured\n' +
        '/sensors           every channel and what it reads right now\n' +
        '/sensorname D5 Bilge  name a channel on a device\n' +
        '/sensoralert D5 open  when a switch should alert\n' +
        '/limits bus0 12000 14500  alert outside a range\n' +
        '/alerts            where your alerts go\n' +
        '/email on|off      turn email alerts on or off\n' +
        '/mute 2h           silence everything for a while\n' +
        '/unmute            start telling me again\n' +
        '/claim 676358      take on a device (code is on its screen)\n' +
        '/rename 676358 Renko  give a device a proper name\n' +
        '/release NAME      hand a device to someone else' +
        (isAdmin ? '\n/invite NAME       pairing link for someone else (admin)' : '') +
        '\n\nType / to see this list any time.',
        [[{ text: 'Status', callback_data: 'status' }]]
    )];
}

return [null, reply("I didn't understand that. Type / for the list.")];

// ── shared reading renderer ─────────────────────────────────────────────────
// Generated into both "Verbose digest" and "Format reply" so a reading looks
// identical whether you asked for it (/status) or it arrived on a feed
// (/watch). If you edit this block in one node, edit it in the other.
function renderReading(s, d) {
    const L = [];
    if (!s) { L.push('   (nothing received yet)'); return L; }

    const r = s.radio;
    const bits = [];
    if (r) {
        if (r.rssi !== undefined && r.rssi !== null) bits.push('rssi ' + r.rssi);
        if (r.snr  !== undefined && r.snr  !== null) bits.push('snr ' + r.snr);
        if (r.freq !== undefined && r.freq !== null) bits.push(Number(r.freq).toFixed(1) + 'MHz');
    }
    if (s.counter !== undefined) bits.unshift('#' + s.counter);
    if (bits.length) L.push('   ' + bits.join('   '));

    if (s.battery !== undefined) {
        L.push('   transmitter ' + s.battery + '%' +
               (s.voltage ? '  (' + (s.voltage / 1000).toFixed(2) + 'V)' : ''));
    }

    const labelFor = (list, idx) => {
        if (!list) return null;
        const p = list.find(x => x && x.pin_index === idx);
        return (p && p.label) ? p : null;
    };
    // Only judge a channel that is actually being watched. A pin with
    // alert_level 'None' has thresholds nobody has validated - printing "LOW"
    // against one states as fact something the system has deliberately been
    // told to ignore.
    const within = (p, v) => {
        if (!p) return '';
        if (p.alert_level === 'None' || p.trigger === 'None') return '   (not alerting)';
        if (p.low_threshold  !== null && p.low_threshold  !== undefined && v < p.low_threshold)  return '  LOW';
        if (p.high_threshold !== null && p.high_threshold !== undefined && v > p.high_threshold) return '  HIGH';
        return '  ok';
    };
    const pad = t => (t.length >= 22 ? t + ' ' : t + ' '.repeat(22 - t.length));

    // I2C bus. Slot values are millivolts on an INA219.
    if (s.bus && Array.isArray(s.bus.slots)) {
        const n = s.bus.discoveredSensors;
        if (!n) {
            L.push('   bus: nothing discovered');
        } else {
            s.bus.slots.forEach((v, i) => {
                const p = labelFor(d.bus_pins, i);
                if (!p && !v) return;
                const name = p ? p.label : 'slot ' + i;
                const val  = v > 1000 ? (v / 1000).toFixed(2) + ' V' : String(v);
                L.push('   ' + pad(name) + val + within(p, v));
            });
        }
    }

    if (s.gpio && Array.isArray(s.gpio.analog)) {
        s.gpio.analog.forEach((v, i) => {
            const p = labelFor(d.analog_pins, i);
            if (!p) return;                     // unlabelled analog is noise
            L.push('   ' + pad(p.label) + v + within(p, v));
        });
    }

    if (s.gpio && s.gpio.digitalBitmask !== undefined) {
        (d.digital_pins || []).forEach(p => {
            if (!p || !p.label) return;
            const bit = (s.gpio.digitalBitmask >> p.pin_index) & 1;
            const tripped = (p.trigger === 'High' && bit === 1) || (p.trigger === 'Low' && bit === 0);
            const verdict = (p.trigger === 'None' || !p.trigger) ? '   (not alerting)'
                          : (tripped ? '  TRIGGERED' : '  ok');
            L.push('   ' + pad(p.label) + (bit ? 'ON' : 'OFF') + verdict);
        });
    }
    return L;
}


// ── reply builder ───────────────────────────────────────────────────────────
const action = msg.tgAction;
const rows   = msg.payload || [];
const tg     = msg.tg;
const owner  = msg.tgOwner || {};
const out    = { tgChatId: tg.chatId, tgCallbackId: tg.callbackId || null };

const TZ = env.get('TZ') || 'Australia/Sydney';
const clock = ts => new Date(ts).toLocaleTimeString('en-AU',
    { hour: '2-digit', minute: '2-digit', hour12: false, timeZone: TZ });
const ago = sec => {
    if (sec === null || sec === undefined) return 'never heard from';
    sec = Math.floor(Number(sec));
    if (sec < 90)     return sec + 's ago';
    if (sec < 5400)   return Math.round(sec / 60) + 'm ago';
    if (sec < 172800) return Math.round(sec / 3600) + 'h ago';
    return Math.round(sec / 86400) + 'd ago';
};

switch (action) {

case 'pair': {
    // No row means a wrong or already-redeemed token. Say both: the usual cause
    // is tapping an older email after having already paired.
    if (!rows.length) {
        out.tgText = "That code didn't work - it may already have been used.\n\n" +
                     'Try the link in your most recent SensorSentinel email.';
        break;
    }
    const o = rows[0];
    out.tgText = 'Connected, ' + o.name + '.\n\n' +
                 'You have ' + o.device_count + ' device' + (o.device_count == 1 ? '' : 's') +
                 '. Type / to see what I can do.\n\nWhere would you like alerts?';
    out.tgButtons = [[{ text: 'Here', callback_data: 'notify:here' },
                      { text: 'Email', callback_data: 'notify:email' },
                      { text: 'Both', callback_data: 'notify:both' }]];
    break;
}

case 'mute': {
    const o = rows[0] || {};
    const MTZ = env.get('TZ') || 'Australia/Sydney';
    if (o.indefinite) {
        out.tgText = 'Everything is muted, on every channel, until you send /unmute.\n\n' +
                     'Nothing will reach you meanwhile - not a low battery, not a\n' +
                     'bilge float, not a device going offline.';
    } else {
        const until = new Date(Date.now() + Number(o.secs_left || 0) * 1000);
        out.tgText = 'Muted until ' + until.toLocaleTimeString('en-AU',
                        { hour: '2-digit', minute: '2-digit', hour12: false, timeZone: MTZ }) +
                     ', then alerts resume by themselves.\n\n' +
                     'Nothing reaches you before then, on any channel.';
    }
    out.tgButtons = [[{ text: 'Unmute now', callback_data: 'unmute' }]];
    break;
}

case 'unmute': {
    const o = rows[0] || {};
    const where = { telegram: 'here in Telegram', email: 'by email',
                    both: 'here and by email', none: 'nowhere' }[o.notify_via] || o.notify_via;
    out.tgText = 'Unmuted. Alerts will reach you ' + where + ' again.';
    break;
}

case 'notify': {
    const o = rows[0] || {};
    const where = { telegram: 'here in Telegram', email: 'by email',
                    both: 'here and by email', none: 'nowhere' }[o.notify_via] || o.notify_via;
    out.tgText = 'Done - alerts will go ' + where + '.';
    break;
}

case 'status': {
    if (!rows.length) {
        out.tgText = 'Nothing matched. Type /info to see what you own.';
        break;
    }
    const blocks = rows.map(d => {
        // A node that has gone quiet looks exactly like a node with nothing to
        // report, so silence has to be called out rather than left to be noticed.
        const quiet = (d.age_sec === null || Number(d.age_sec) > 1800) ? '   ** QUIET **' : '';
        const head = d.display_name + '        ' + ago(d.age_sec) + quiet;
        const watching = d.verbose_active
            ? ['   watching until ' + clock(Date.now() + (d.verbose_secs_left || 0) * 1000)] : [];
        return [head].concat(renderReading(d.last_payload, d), watching).join('\n');
    });
    out.tgText = blocks.join('\n\n');
    if (rows.length === 1) {
        out.tgButtons = [[{ text: 'Watch 30m', callback_data: 'watch:' + rows[0].node_id + ':30' }]];
    } else {
        out.tgButtons = [[{ text: 'Watch all 30m', callback_data: 'watch::30' }]];
    }
    break;
}

case 'info': {
    if (!rows.length) { out.tgText = 'You have no devices registered yet.'; break; }
    const L = [owner.name + (owner.is_admin ? '   (admin)' : ''),
               'Alerts: ' + owner.notify_via,
               rows.length + ' device' + (rows.length === 1 ? '' : 's'), ''];
    rows.forEach(d => {
        L.push(d.display_name + '        node ' + d.node_id);
        L.push('   quiet after ' + d.stale_after_minutes + ' min' +
               (d.watchdog_enabled ? '' : '   (watchdog off)'));
        const bounds = p => {
            const b = [];
            if (p.low_threshold  !== null && p.low_threshold  !== undefined) b.push('low ' + p.low_threshold);
            if (p.high_threshold !== null && p.high_threshold !== undefined) b.push('high ' + p.high_threshold);
            return b.length ? '   ' + b.join('  ') : '   no limits set';
        };
        (d.bus_pins || []).forEach(p => L.push('   bus ' + p.pin_index + '   ' + p.label + bounds(p)));
        (d.analog_pins || []).forEach(p => L.push('   A' + p.pin_index + '    ' + p.label + bounds(p)));
        (d.digital_pins || []).forEach(p => L.push('   D' + p.pin_index + '    ' + p.label + '   alerts when ' + p.trigger));
        L.push('');
    });
    out.tgText = L.join('\n').trim();
    break;
}

case 'name': {
    if (!rows.length) {
        out.tgText = "I couldn't work out which device you meant, or that channel " +
                     'does not exist.\n\n' +
                     'With more than one device, name it first:\n' +
                     '    /sensorname renko D5 Bilge float';
        break;
    }
    const r = rows[0];
    // Say plainly that it is not armed yet. A named channel with nothing set
    // looks configured in /info and stays silent for ever - which is exactly
    // how "Main Power Supply" ended up dormant.
    // Do not point at commands that do not exist yet - being told to run
    // something that then fails is worse than being told nothing.
    const next = msg.tgKind === 'd'
        ? 'It will not raise an alert yet: something still has to say whether\n' +
          'open or closed is the state worth telling you about.'
        : 'It will not raise an alert yet: it still needs a limit, set against\n' +
          'what it actually reads. /sensors shows you the current value.';
    out.tgText = 'Named ' + msg.tgChannel + ' "' + r.label + '" on ' + r.device_name + '.\n\n' +
                 'It now shows up in /info and /status.\n\n' + next;
    break;
}

case 'sensoralert': {
    if (!rows.length) {
        out.tgText = "I couldn't work out which device you meant, or that input does not exist." +
                     '\n\nWith more than one device, name it first:\n    /sensoralert renko D5 open';
        break;
    }
    const r = rows[0];
    const what = (r.label && r.label !== '') ? r.label : ('D' + r.pin_index);
    // Both directions spelled out. Half the value of a transition alert is
    // knowing which way round it is, and "trigger: High" does not say.
    const say = {
        High:   what + ' will ALERT when it opens,\nand RESOLVE when it closes again.',
        Low:    what + ' will ALERT when it closes,\nand RESOLVE when it opens again.',
        Change: what + ' will report every change, both ways,\nwithout calling either one an alarm.',
        None:   what + ' will not alert at all now.'
    }[r.trigger] || ('Set to ' + r.trigger + '.');
    out.tgText = say + '\n\nOn ' + r.device_name + '. /sensors shows its state right now.';
    break;
}

case 'limits': {
    if (!rows.length) {
        out.tgText = "I couldn't work out which device you meant, or that channel does not exist." +
                     '\n\nWith more than one device, name it first:\n    /limits renko bus0 12000 14500';
        break;
    }
    const r = rows[0];
    const what = (r.label && r.label !== '') ? r.label : msg.tgChannel;
    if (r.alert_level === 'None') {
        out.tgText = what + ' will not alert now.\nIts limits are cleared.';
        break;
    }
    const s = r.last_payload || {};
    const now = msg.tgKind === 'bus'
        ? (((s.bus && s.bus.slots) || [])[msg.tgIndex])
        : (((s.gpio && s.gpio.analog) || [])[msg.tgIndex]);
    const parts = [];
    if (r.low_threshold  !== null && r.low_threshold  !== undefined) parts.push('below ' + r.low_threshold);
    if (r.high_threshold !== null && r.high_threshold !== undefined) parts.push('above ' + r.high_threshold);
    let txt = what + ' will alert ' + parts.join(' or ') + '.';
    if (now !== undefined && now !== null) {
        txt += '\n\nIt currently reads ' + now + '.';
        // Say so plainly rather than let a units mistake sit there quietly -
        // this is exactly how a threshold of 12 ended up against a raw reading.
        const lo = r.low_threshold, hi = r.high_threshold;
        if ((lo !== null && lo !== undefined && Number(now) < Number(lo)) ||
            (hi !== null && hi !== undefined && Number(now) > Number(hi))) {
            txt += '\nThat is already outside the range - check the units match\nbefore you rely on it.';
        }
    }
    out.tgText = txt + '\n\nOn ' + r.device_name + '.';
    break;
}

case 'sensors': {
    if (!rows.length) { out.tgText = 'Nothing matched. /info lists your devices.'; break; }
    const blocks = rows.map(d => {
        const s = d.last_payload || {};
        const L = [d.display_name + '        ' + ago(d.age_sec)];
        const find = (list, i) => (list || []).find(x => x && x.pin_index === i) || null;
        const named = p => (p && p.label) ? p.label : '(unnamed)';
        const arm = p => (!p || !p.label) ? '  not alerting'
                       : (p.alert_level === 'None' || p.trigger === 'None') ? '  not alerting' : '';

        // Bus - every slot that is reading something or has been named.
        const bus = [];
        ((s.bus && s.bus.slots) || []).forEach((v, i) => {
            const p = find(d.bus_pins, i);
            if (!v && !(p && p.label)) return;
            const val = v > 1000 ? (v / 1000).toFixed(2) + ' V' : String(v);
            bus.push('   bus' + i + '  ' + named(p).padEnd(20) + val + arm(p));
        });
        if (bus.length) {
            L.push('Bus  (' + ((s.bus && s.bus.discoveredSensors) || 0) + ' found)');
            L.push(...bus);
        }

        // Analog - all four, since there are only four and one may be new.
        const an = ((s.gpio && s.gpio.analog) || []);
        if (an.length) {
            L.push('Analog');
            an.forEach((v, i) => {
                const p = find(d.analog_pins, i);
                L.push('   A' + i + '    ' + named(p).padEnd(20) + v + arm(p));
            });
        }

        // Digital - a compact map. An unconnected input reads 1 (INPUT_PULLUP),
        // so a wired-but-open switch is indistinguishable from nothing at all.
        // The reliable way to find a new one is to toggle it and look for the
        // bit that moved, which is what the hint below tells you to do.
        if (s.gpio && s.gpio.digitalBitmask !== undefined) {
            // Only eight inputs exist. SensorSentinel_BOOLEAN_PINS pads slots
            // 8-15 with zeros, so those bits always read 0 - which under a
            // legend saying "0 means something is pulling it down" would send
            // you looking for hardware that is not there.
            const GPIO = [33, 34, 35, 39, 40, 41, 42, 46];   // Heltec V3 / V3.2
            const m = s.gpio.digitalBitmask;
            const row = [];
            for (let i = 0; i < GPIO.length; i++) row.push('D' + i + ':' + ((m >> i) & 1));
            L.push('Digital  (1 = open, nothing pulling it down)');
            for (let i = 0; i < row.length; i += 4) L.push('   ' + row.slice(i, i + 4).join('  '));
            (d.digital_pins || []).forEach(p => {
                if (!p || !p.label || p.pin_index >= GPIO.length) return;
                L.push('   D' + p.pin_index + ' = ' + p.label +
                       '  (GPIO' + GPIO[p.pin_index] + ')' + arm(p));
            });
        }
        return L.join('\n');
    });
    out.tgText = blocks.join('\n\n') +
        '\n\nTo find an unlabelled switch, toggle it and run /sensors again -' +
        '\nthe digit that changed is yours.';
    break;
}

case 'watch': {
    if (!rows.length) {
        out.tgText = "I couldn't work out which device you meant.\n\n" +
                     'Type /info to see the names, then /watch NAME.';
        break;
    }
    const names = rows.map(d => d.display_name).join(', ');
    // Seconds-remaining from the database, turned into a local clock time here.
    const secs = rows[0].verbose_secs_left || 0;
    const mins = Math.max(1, Math.round(secs / 60));
    out.tgText = 'Watch started for ' + names + '.\n\n' +
                 'You will get every reading as it arrives, roughly one every 30 seconds.\n\n' +
                 'Runs for ' + mins + ' minutes (until ' + clock(Date.now() + secs * 1000) + '), ' +
                 'or until you send /unwatch.';
    out.tgButtons = [[{ text: 'Stop now', callback_data: 'unwatch' }]];
    break;
}

case 'unwatch':
    out.tgText = rows.length
        ? 'Stopped watching ' + rows.map(d => d.display_name).join(', ') + '.'
        : 'Nothing was being watched.';
    break;

case 'claim': {
    // No row means the code matched nothing claimable. Two causes worth
    // separating, because they need different actions: wrong code, or the
    // device already has an owner who must release it first.
    if (!rows.length) {
        out.tgText = "That code didn't match anything I can hand over.\n\n" +
                     'Either the characters are wrong - press the button again and\n' +
                     'check the screen - or the device already belongs to someone,\n' +
                     'in which case they need to release it first.';
        break;
    }
    const d = rows[0];
    // Straight off auto-registration it is called Node-33676358, which tells a
    // person nothing. Ask for a real name rather than leaving them with that.
    out.tgText = d.unnamed
        ? ('Claimed, ' + d.owner_name + ' - but it is still called ' + d.display_name + '.\n\n' +
           'What should I call it?\n    /rename ' + d.claim_code + ' Renko')
        : (d.display_name + ' is yours now, ' + d.owner_name + '.\n\n' +
           'Type / to see what I can do, or /status to see how it is doing.');
    out.tgButtons = [[{ text: 'Status', callback_data: 'status' }],
                     [{ text: 'Alerts here', callback_data: 'notify:here' },
                      { text: 'Email', callback_data: 'notify:email' },
                      { text: 'Both', callback_data: 'notify:both' }]];
    break;
}

case 'rename': {
    out.tgText = rows.length
        ? 'Renamed to ' + rows[0].display_name + '.'
        : "I couldn't find that device among yours. /info lists them.";
    break;
}

case 'release': {
    if (!rows.length) {
        out.tgText = "I couldn't find that device among yours. /info lists them.";
        break;
    }
    const d = rows[0];
    out.tgText = 'Released ' + d.display_name + '.\n\n' +
                 'It now belongs to nobody, and any feed on it has stopped.\n\n' +
                 'Whoever takes it on should press its button and send me the six\n' +
                 'characters on its screen:\n    /claim ' + d.claim_code + '\n\n' +
                 'Until someone claims it, no alerts will be sent for it.';
    break;
}

case 'invite': {
    if (!rows.length) {
        out.tgText = 'No unpaired owner by that name - check the spelling, ' +
                     'or they may already be connected.';
        break;
    }
    const o = rows[0];
    const bot = global.get('tgBotUsername');
    out.tgText = 'Invite for ' + o.name + ':\n\n' +
                 (bot ? 'https://t.me/' + bot + '?start=' + o.pair_code
                      : 'Code: ' + o.pair_code + '   (bot username not known yet)') +
                 '\n\nOne tap connects them. Good until used.';
    break;
}

default:
    out.tgText = 'Done.';
}

return out;

// ── shared reading renderer ─────────────────────────────────────────────────
// Generated into both "Verbose digest" and "Format reply" so a reading looks
// identical whether you asked for it (/status) or it arrived on a feed
// (/watch). If you edit this block in one node, edit it in the other.
function renderReading(s, d) {
    const L = [];
    if (!s) { L.push('   (nothing received yet)'); return L; }

    const r = s.radio;
    const bits = [];
    if (r) {
        if (r.rssi !== undefined && r.rssi !== null) bits.push('rssi ' + r.rssi);
        if (r.snr  !== undefined && r.snr  !== null) bits.push('snr ' + r.snr);
        if (r.freq !== undefined && r.freq !== null) bits.push(Number(r.freq).toFixed(1) + 'MHz');
    }
    if (s.counter !== undefined) bits.unshift('#' + s.counter);
    if (bits.length) L.push('   ' + bits.join('   '));

    if (s.battery !== undefined) {
        L.push('   transmitter ' + s.battery + '%' +
               (s.voltage ? '  (' + (s.voltage / 1000).toFixed(2) + 'V)' : ''));
    }

    const labelFor = (list, idx) => {
        if (!list) return null;
        const p = list.find(x => x && x.pin_index === idx);
        return (p && p.label) ? p : null;
    };
    // Only judge a channel that is actually being watched. A pin with
    // alert_level 'None' has thresholds nobody has validated - printing "LOW"
    // against one states as fact something the system has deliberately been
    // told to ignore.
    const within = (p, v) => {
        if (!p) return '';
        if (p.alert_level === 'None' || p.trigger === 'None') return '   (not alerting)';
        if (p.low_threshold  !== null && p.low_threshold  !== undefined && v < p.low_threshold)  return '  LOW';
        if (p.high_threshold !== null && p.high_threshold !== undefined && v > p.high_threshold) return '  HIGH';
        return '  ok';
    };
    const pad = t => (t.length >= 22 ? t + ' ' : t + ' '.repeat(22 - t.length));

    // I2C bus. Slot values are millivolts on an INA219.
    if (s.bus && Array.isArray(s.bus.slots)) {
        const n = s.bus.discoveredSensors;
        if (!n) {
            L.push('   bus: nothing discovered');
        } else {
            s.bus.slots.forEach((v, i) => {
                const p = labelFor(d.bus_pins, i);
                if (!p && !v) return;
                const name = p ? p.label : 'slot ' + i;
                const val  = v > 1000 ? (v / 1000).toFixed(2) + ' V' : String(v);
                L.push('   ' + pad(name) + val + within(p, v));
            });
        }
    }

    if (s.gpio && Array.isArray(s.gpio.analog)) {
        s.gpio.analog.forEach((v, i) => {
            const p = labelFor(d.analog_pins, i);
            if (!p) return;                     // unlabelled analog is noise
            L.push('   ' + pad(p.label) + v + within(p, v));
        });
    }

    if (s.gpio && s.gpio.digitalBitmask !== undefined) {
        (d.digital_pins || []).forEach(p => {
            if (!p || !p.label) return;
            const bit = (s.gpio.digitalBitmask >> p.pin_index) & 1;
            const tripped = (p.trigger === 'High' && bit === 1) || (p.trigger === 'Low' && bit === 0);
            const verdict = (p.trigger === 'None' || !p.trigger) ? '   (not alerting)'
                          : (tripped ? '  TRIGGERED' : '  ok');
            L.push('   ' + pad(p.label) + (bit ? 'ON' : 'OFF') + verdict);
        });
    }
    return L;
}


// ── verbose digest ──────────────────────────────────────────────────────────
// Hangs off the device lookup, not the alert path: it must report what arrived
// whether or not anything crossed a threshold. That is the whole point - it
// answers "is this thing being heard at all", which is the question you have
// precisely when no alerts are coming.

const rows = msg.payload || [];
if (!rows.length) return null;
const d = rows[0];

// Expired or never armed. The timestamp is the safety catch: whoever started
// this may be out of signal by now and unable to stop it.
if (!d.verbose_active) return null;
if (!d.verbose_chat_id) return null;

const s = msg.sensorData || {};
if (msg.gateway && !s.radio) s.radio = msg.gateway;

const TZ = env.get('TZ') || 'Australia/Sydney';
const lines = [d.display_name].concat(renderReading(s, d));
// Built from seconds-remaining, never from the stored timestamp, so the clock
// shown is this machine's local time and cannot drift with the database.
const endsAt = new Date(Date.now() + (d.verbose_secs_left || 0) * 1000);
lines.push('   until ' + endsAt.toLocaleTimeString('en-AU',
    { hour: '2-digit', minute: '2-digit', hour12: false, timeZone: TZ }) + ', or /unwatch');

node.status({ fill: 'blue', shape: 'dot', text: 'feed -> ' + d.display_name });

return {
    tgChatId: d.verbose_chat_id,
    tgText: lines.join('\n'),
    tgButtons: [[{ text: 'Stop', callback_data: 'off:' + s.nodeId },
                 { text: 'Another 30m', callback_data: 'watch:' + s.nodeId + ':30' }]]
};

// Anyone in the system who has never been welcomed. Polling rather than a
// database trigger, so it does not matter how the owner got created - NocoDB,
// psql, or a signup form that does not exist yet.
msg.query = `SELECT o.id, o.name, o.email, o.pair_code, o.telegram_chat_id,
                    COALESCE((SELECT string_agg(d.display_name, ', ' ORDER BY d.display_name)
                                FROM devices d WHERE d.owner_id = o.id), '') AS devices
               FROM owners o
              WHERE o.welcome_sent_at IS NULL
                AND o.email IS NOT NULL AND o.email <> ''`;
msg.params = [];
return msg;

// Send the one-time welcome, and mark it sent.
//
// The pairing token is minted here if the owner has none: this is the first
// time anyone has needed one, and it lets the link go out in the same message
// that explains what it is for.

const rows = msg.payload || [];
if (!rows.length) return null;

const user = env.get('NOTIFY_EMAIL_USER');
const pass = env.get('NOTIFY_EMAIL_PASS');
if (!pass) { node.error('NOTIFY_EMAIL_PASS not set - cannot send welcome'); return null; }

const mkToken = () => {
    const abc = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    // Node's crypto module, not globalThis.crypto - Node-RED runs function
    // nodes in a vm context that does not inherit Web Crypto, so the global is
    // undefined here even on Node 20.
    const buf = nodeCrypto.randomBytes(16);
    let out = '';
    for (let i = 0; i < 16; i++) out += abc[buf[i] % abc.length];
    return out;
};

// The welcome is one-shot, so it must not go out half-formed. If a bot token
// is configured but its username has not been fetched yet - the first minute
// after a restart - wait and try again, rather than sending a welcome with the
// invitation missing that nobody will ever be sent again.
const botName = global.get('tgBotUsername');
if (env.get('TELEGRAM_BOT_TOKEN') && !botName) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'waiting for bot username' });
    return null;
}

const transporter = nodemailer.createTransport({
    host: env.get('NOTIFY_SMTP_HOST') || 'smtp.gmail.com',
    port: 465, secure: true, auth: { user: user, pass: pass }
});

for (const o of rows) {
    const token = o.pair_code || mkToken();

    // Already on Telegram: this is a re-welcome after an address change, so
    // do not pitch them something they are using.
    const telegram = (botName && !o.telegram_chat_id) ? `
Prefer Telegram? (optional)
---------------------------
Telegram can do things email cannot: ask how your boat is doing right now,
watch live readings while you are standing on the dock, and get alerts the
moment they happen. One tap connects it:

    https://t.me/${botName}?start=${token}

You can still have alerts by email, or both - it asks you when you connect.
Nothing to install if you would rather not; email works on its own.
` : '';

    const body = `Hello ${o.name},

Welcome to SensorSentinel.

It keeps an eye on your boat while you are not on it, and tells you when
something changes.

Devices and sensors
-------------------
A *device* is the small unit fitted to the boat. Each device can carry
several *sensors*, and which ones is up to you. Two common examples:

  * A battery monitor - so you know if the charger has stopped keeping up,
    long before a flat battery becomes your problem
  * A bilge float switch - so you know if water is coming in

Those are only examples. Other sensors are supported, and one device can
carry several at once.

How the readings reach you
--------------------------
The device takes a reading every 30 seconds and sends it by LoRa radio -
long range and very low power, so there is no wifi and no SIM card on the
boat, and it runs for months on a single cell. A small gateway on the jetty
picks the readings up and passes them to a server at home.

When you will hear from us
--------------------------
Only when something changes:

  * A reading crosses a limit - battery below 12 volts, say - and again
    when it returns to normal.
  * A device goes quiet. This one matters: a sensor that has stopped
    reporting looks exactly like a sensor saying "all fine", so we watch
    for the silence itself and tell you about it.

The rest of the time you hear nothing, and that is the point of it.

Your devices
------------
${o.devices ? '    ' + o.devices : '    (none registered yet)'}
${telegram}
--
SensorSentinel
`;

    transporter.sendMail({
        from: '"SensorSentinel" <' + user + '>',
        to: o.email,
        subject: 'Welcome to SensorSentinel',
        text: body
    }).then(() => {
        node.warn('Welcome email sent to ' + o.name + ' <' + o.email + '>');
    }).catch(err => {
        node.error('Welcome email to ' + o.email + ' failed: ' + err.message);
    });

    // Marked immediately rather than on delivery confirmation: a transient SMTP
    // failure retried every minute for ever is worse than one missed welcome,
    // which an admin can reissue with /invite.
    node.send({
        query: `UPDATE owners SET pair_code = COALESCE(pair_code, $2),
                                  welcome_sent_at = NOW(), updated_at = NOW()
                 WHERE id = $1`,
        params: [o.id, token],
        payload: ''
    });
}
return null;
